steps.body:
A mapped type builds an object type from the keys of another. `[K in keyof T]` goes through the keys of `T` one at a time, with `K` holding the current key, and the type after the colon is what that key holds in the new type:

```typescript types
type Settings = { theme: string; fontSize: number };

type Flags<T> = { [K in keyof T]: boolean };
type Changed = Flags<Settings>;
//   ^? type Changed = { theme: boolean; fontSize: boolean; }
```

After the colon you can use `T[K]`, the type the key holds in `T`. So `{ [K in keyof T]: T[K] }` is an exact copy of `T`, and anything else changes every key the same way. A `?` after the brackets makes every key optional.

A mapped type follows the type it maps. Add a key to `Settings`, and `Flags<Settings>` gains that key too, so every value typed with it must handle the new key before the code compiles again.

examples.code:
type Features = {
  darkMode: { theme: string };
  search: { maxResults: number };
  csvExport: { delimiter: string };
};

type Flags<T> = { [K in keyof T]: boolean };

type FeatureFlags = Flags<Features>;
//   ^? type FeatureFlags = { darkMode: boolean; search: boolean; csvExport: boolean; }

const free: FeatureFlags = { darkMode: true, search: true, csvExport: false };
const pro: FeatureFlags = { ...free, csvExport: true };

function enabled(flags: FeatureFlags): string {
  return Object.entries(flags)
    .filter(([, on]) => on)
    .map(([name]) => name)
    .join(", ");
}

console.log(`free: ${enabled(free)}`);
console.log(`pro: ${enabled(pro)}`);

examples.explanation:
`Features` describes the settings of each feature. `Flags<Features>` keeps its three keys and gives every one the type `boolean`, as the bubble shows. What the keys held before doesn't matter here, only their names. A plan's flags must name every feature, so a plan that forgets one doesn't compile:

```typescript error
type Features = { darkMode: { theme: string }; search: { maxResults: number } };
type Flags<T> = { [K in keyof T]: boolean };

const trial: Flags<Features> = { darkMode: true };
```

`tsc` reports TS2741, `Property 'search' is missing`. That's the reason to derive the type: add a feature to `Features`, and `tsc` points at every plan that hasn't decided whether to turn it on.

examples.code:
type ContactForm = { name: string; email: string; message: string };

type Validators<T> = { [K in keyof T]: (value: T[K]) => string | null };

const validators: Validators<ContactForm> = {
  name: (value) => (value.trim() === "" ? "is required" : null),
  email: (value) => (value.includes("@") ? null : "needs an @"),
  message: (value) => (value.length >= 10 ? null : "is too short"),
};

const FIELDS = ["name", "email", "message"] as const satisfies readonly (keyof ContactForm)[];

function problems(form: ContactForm): string[] {
  const found: string[] = [];
  for (const field of FIELDS) {
    const problem = validators[field](form[field]);
    if (problem !== null) found.push(`${field} ${problem}`);
  }
  return found;
}

const forms: ContactForm[] = [
  { name: "Ada", email: "ada@example.com", message: "Hello from London!" },
  { name: " ", email: "grace.example.com", message: "Hi" },
];

for (const form of forms) {
  const found = problems(form);
  console.log(found.length === 0 ? "ok" : found.join(", "));
}

type ProfileForm = { username: string; bio: string; website: string };

type FieldErrors<T> = { [K in keyof T]?: string };

function validateProfile(form: ProfileForm): FieldErrors<ProfileForm> {
  const errors: FieldErrors<ProfileForm> = {};
  if (form.username.length < 3) {
    errors.username = "must be at least 3 characters";
  }
  if (form.bio.length > 160) {
    errors.bio = "must be at most 160 characters";
  }
  if (!form.website.startsWith("https://")) {
    errors.website = "must start with https://";
  }
  return errors;
}

const good = validateProfile({ username: "ada", bio: "Writes programs.", website: "https://ada.dev" });
const bad = validateProfile({ username: "al", bio: "", website: "http://al.dev" });

console.log(JSON.stringify(good));
console.log(JSON.stringify(bad));

