export type SignupForm = { email: string; password: string; age: number };

export type FieldErrors<T> = { [K in keyof T]?: string };

export function validate(form: SignupForm): FieldErrors<SignupForm> {
  const errors: FieldErrors<SignupForm> = {};
  if (!form.email.includes("@")) {
    errors.email = "must contain @";
  }
  if (form.password.length < 8) {
    errors.password = "must be at least 8 characters";
  }
  if (form.age < 13) {
    errors.age = "must be at least 13";
  }
  return errors;
}

const forms: SignupForm[] = [
  { email: "ada@example.com", password: "correct-horse", age: 36 },
  { email: "grace.example.com", password: "battery-staple", age: 12 },
];

for (const form of forms) {
  console.log(JSON.stringify(validate(form)));
}

steps.body:
A mapped type over `keyof T` copies each key's modifiers: a `readonly` key stays `readonly`, and an optional key stays optional. You can also change them for every key at once. Write `readonly` before the brackets and `?` after them, as in an object type. A `-` in front of either removes it, and a `+`, the default, adds it:

```typescript types
type Article = { readonly id: string; title: string; body?: string };

type Editable = { -readonly [K in keyof Article]: Article[K] };
//   ^? type Editable = { id: string; title: string; body?: string; }
type Complete = { [K in keyof Article]-?: Article[K] };
//   ^? type Complete = { readonly id: string; title: string; body: string; }
```

`-?` also drops the `undefined` that reading an optional key adds, so `body` is a plain `string` in `Complete`.

That's all there is to three of the utility types. TypeScript's own library declares `Partial<T>` as `{ [P in keyof T]?: T[P] }`, `Required<T>` as `{ [P in keyof T]-?: T[P] }`, and `Readonly<T>` as `{ readonly [P in keyof T]: T[P] }`.

examples.code:
type MyPartial<T> = { [K in keyof T]?: T[K] };

type User = { id: number; name: string; email: string };

type Patch = MyPartial<User>;
//   ^? type Patch = { id?: number; name?: string; email?: string; }
type BuiltIn = Partial<User>;
//   ^? type BuiltIn = { id?: number; name?: string; email?: string; }

function update(user: User, patch: MyPartial<User>): User {
  return { ...user, ...patch };
}

const ada: User = { id: 1, name: "Ada", email: "ada@example.com" };
const newEmail: Partial<User> = { email: "ada@lovelace.dev" };

console.log(JSON.stringify(update(ada, { name: "Ada Lovelace" })));
console.log(JSON.stringify(update(ada, newEmail)));

type Invoice = {
  readonly id: string;
  readonly lines: readonly string[];
  readonly totalCents: number;
};

type Mutable<T> = { -readonly [K in keyof T]: T[K] };

function buildInvoice(id: string, items: [name: string, cents: number][]): Invoice {
  const invoice: Mutable<Invoice> = { id, lines: [], totalCents: 0 };
  for (const [name, cents] of items) {
    invoice.lines = [...invoice.lines, `${name}: $${(cents / 100).toFixed(2)}`];
    invoice.totalCents += cents;
  }
  return invoice;
}

const invoice = buildInvoice("INV-7", [
  ["Notebook", 900],
  ["Fountain pen", 2599],
]);

console.log(invoice.id);
for (const line of invoice.lines) {
  console.log(`  ${line}`);
}
console.log(`Total: $${(invoice.totalCents / 100).toFixed(2)}`);

type Concrete<T> = { [K in keyof T]-?: T[K] };

type RetryOptions = { retries?: number; delayMs?: number; verbose?: boolean };

const DEFAULTS: Concrete<RetryOptions> = { retries: 3, delayMs: 500, verbose: false };

function resolve(options: RetryOptions): Concrete<RetryOptions> {
  return { ...DEFAULTS, ...options };
}

const options = resolve({ retries: 5 });
const total = options.retries * options.delayMs;
//    ^? const total: number

console.log(JSON.stringify(options));
console.log(`Waits up to ${total} ms in all`);

