type UploadEvents = {
  started: { file: string };
  progress: { file: string; percent: number };
  finished: { file: string; bytes: number };
};

type Handlers<E> = { [K in keyof E as `on${Capitalize<string & K>}`]: (payload: E[K]) => void };

const handlers = {
  onStarted: (e) => console.log(`Uploading ${e.file}`),
  onProgress: (e) => console.log(`${e.file}: ${e.percent}%`),
  onFinished: (e) => console.log(`${e.file}: ${e.bytes} bytes`),
} satisfies Handlers<UploadEvents>;

handlers.onStarted({ file: "photo.jpg" });
handlers.onProgress({ file: "photo.jpg", percent: 50 });
handlers.onFinished({ file: "photo.jpg", bytes: 204800 });

