export type CartEvents = {
  added: { sku: string };
  removed: { sku: string };
  cleared: { at: string };
};

export type Handlers<E> = { [K in keyof E as `on${Capitalize<string & K>}`]: (payload: E[K]) => void };

export const handlers = {
  onAdded: (e) => console.log(`Added ${e.sku}`),
  onRemoved: (e) => console.log(`Removed ${e.sku}`),
  onCleared: (e) => console.log(`Cart cleared at ${e.at}`),
} satisfies Handlers<CartEvents>;

handlers.onAdded({ sku: "MUG-01" });
